  id: "JAH-INFO-000001",
  title: "Piktochart",
  kind: "infographic maker",
  developer: "Piktochart",
  platforms: "any modern web browser",
  license: "Freemium"
};
function demo() {
  console.log("=== " + record.title + " ===");
